import {TAU} from '../../public/core.mjs';
import {targetKey,sample} from '../../public/targets.mjs';
const tables=new Map();
export function measuredScore(audio,shape,note,h=32){const base=440*2**((note-69)/12),bands=Math.min(h,Math.floor(23999/base));const key=(typeof shape==='object'?targetKey(shape):shape)+':'+bands;if(tables.size>128)tables.clear();const n=audio.length,table=tables.get(key)||new Float64Array(32768);if(!tables.has(key))for(let i=0;i<table.length;i++){let y=0;const theta=i/table.length*TAU;for(let k=1;k<=bands;k++)y+=shape==='saw'?Math.sin(k*theta)/k:k%2?(shape==='square'?Math.sin(k*theta)/k:Math.cos(k*theta)/(k*k)):0;table[i]=typeof shape==='object'?sample(shape,theta,bands):y}tables.set(key,table);if(table.reduce((s,x)=>s+x*x,0)<1e-12)throw Error('Target is silent at this pitch after Nyquist truncation.');const mean=audio.reduce((s,x)=>s+x,0)/n,centered=Float64Array.from(audio,x=>x-mean),energy=centered.reduce((s,x)=>s+x*x,0),step=base/48000*32768;if(energy<1e-12)return {note,score:0,error:1,shift:0,bands,wave:[],target:[]};const positions=Float64Array.from({length:n},(_,i)=>(i*step)%32768);function at(pos){const idx=Math.floor(pos)&32767,f=pos-Math.floor(pos);return table[idx]*(1-f)+table[(idx+1)&32767]*f}function check(shift){let dot=0,sum=0,squares=0;for(let i=0;i<n;i++){const t=at(positions[i]+shift);sum+=t;squares+=t*t;dot+=centered[i]*t}const et=squares-sum*sum/n;return {score:Math.max(0,Math.min(1,dot/Math.sqrt(energy*et))),scale:dot/energy,shift,targetMean:sum/n}}
let best={score:-1,shift:0};for(let shift=0;shift<32768;shift+=256){const m=check(shift);if(m.score>best.score)best=m}let left=best.shift-256,right=best.shift+256;for(let iter=0;iter<28;iter++){const a=left+(right-left)/3,b=right-(right-left)/3;const x=check(a),y=check(b);if(x.score>best.score)best=x;if(y.score>best.score)best=y;if(x.score<y.score)left=a;else right=b}const viewN=Math.min(n,Math.round(2*48000/base));return {note,score:best.score,error:Math.sqrt(Math.max(0,1-best.score**2)),shift:best.shift,bands,wave:Array.from({length:512},(_,i)=>{const pos=i/511*(viewN-1),idx=Math.floor(pos),f=pos-idx;return ((audio[idx]*(1-f)+audio[Math.min(idx+1,n-1)]*f)-mean)*best.scale}),target:Array.from({length:512},(_,i)=>at((i/511*(viewN-1))*step+best.shift)-best.targetMean)}}
